    def step(self, state):
        t=int(state.get("time",0))
        demand=float(state["demand"]); solar=float(state["solar"])
        flow=self.flow[t] if 0 <= t < len(self.flow) else 0.0
        gen=self.gen[t] if 0 <= t < len(self.gen) else 0.0
        net=demand-solar-flow-gen
        if net > 120.0:
            gen=min(50.0, max(gen, gen+net-120.0)); net=demand-solar-flow-gen
